# Samatwam Ring · GPU renders on Kaggle (v2). Checks the GPU first, time-limits every shot, renders the film's shots at 1080p.
import os, subprocess, base64, time, shutil
W = '/kaggle/working'; T = '/kaggle/tmp'; os.makedirs(T, exist_ok=True); os.chdir(T)
t0 = time.time(); LOG = open(os.path.join(W, 'progress.txt'), 'a')
def log(m): line = f"[{time.time()-t0:7.1f}s] {m}"; print(line, flush=True); LOG.write(line + chr(10)); LOG.flush()
log(subprocess.run('nvidia-smi --query-gpu=name,memory.total --format=csv', shell=True, capture_output=True, text=True).stdout)
if not os.path.exists('blender/blender'):
    subprocess.run('wget -q https://download.blender.org/release/Blender4.5/blender-4.5.16-linux-x64.tar.xz && tar xf blender-4.5.16-linux-x64.tar.xz && mv blender-4.5.16-linux-x64 blender', shell=True, check=True)
subprocess.run('apt-get install -y -q libxi6 libxkbcommon0 libsm6 libxrender1 libxfixes3 libgl1 >/dev/null 2>&1', shell=True)
log('blender ready')
open('ring_film.py', 'w').write(base64.b64decode("").decode())
open('logo_tile.png', 'wb').write(base64.b64decode(""))
out = os.path.join(W, 'renders'); os.makedirs(out + '/stills', exist_ok=True)
def run(args, name, limit):
    s = time.time()
    try: r = subprocess.run('./blender/blender -b -P ring_film.py -- --gpu ' + args, shell=True, capture_output=True, text=True, timeout=limit)
    except subprocess.TimeoutExpired: log(f'{name} TIMED OUT after {limit}s'); return False
    dev = [l for l in r.stdout.splitlines() if 'CYCLES_DEVICE' in l]
    log(f'{name} done in {time.time()-s:.0f}s rc={r.returncode} {dev[:1]}')
    if r.returncode: log(r.stdout[-1500:] + r.stderr[-1500:])
    return r.returncode == 0
# 1 · a quick GPU check: one still at low samples
ok = run(f'--shot black_hero --out {out}/gpu_check.png --samples 32 --res 1920x1080', 'GPU check', 600)
for s in ['white_macro', 'black_hero', 'black_inner', 'black_led', 'white_profile', 'white_flat']:
    run(f'--shot {s} --out {out}/stills/{s}.png --samples 256 --res 1920x1080', s, 900)
for a in ['black_sweep', 'white_turn']:
    os.makedirs(f'{out}/{a}', exist_ok=True); run(f'--shot {a} --anim 90 --out {out}/{a}/#### --samples 128 --res 1920x1080', a, 3600)
shutil.make_archive(os.path.join(W, 'ring_renders'), 'zip', out); shutil.rmtree(out)
log('zipped ' + str(round(os.path.getsize(os.path.join(W, 'ring_renders.zip')) / 1e6, 1)) + ' MB')
